// Shared photo preview: clicks and keyboard activation work in every portal section.
document.addEventListener('click', event => {
  if(!event.target.closest?.('[data-profile-avatar], .student-profile-photo-picker'))return;
  event.preventDefault();
  const student = JSON.parse(sessionStorage.getItem('armiStudent') || 'null');
  if(student)window.armiOpenOwnStudentPhoto?.();
});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches?.('[data-profile-avatar]')){event.preventDefault();event.target.click();}});
